26: import { createWorkerQueue } from './queue.js';
27: import { fabricForStage } from './engine-stage6.js';
28: import { createBrowserSeatRegistry } from './browser-seat.js';
29: import { createUsers } from './users.js';
30: import { createTraceMachine } from './trace.js';
31: import { DEFAULT_TTL_TICKS, DEFAULT_DNS_TTL_TICKS, DEFAULT_SERVICE_RATE } from './defaults.js';
32: import { ROUTER_LEFT_ADDRESS, ROUTER_RIGHT_ADDRESS, CDN_ADDRESS } from './addresses.js';
33: 
34: export function createEngine({
35:   seed = 42,
36:   users = 5,
37:   serviceRate = DEFAULT_SERVICE_RATE,
38:   arrivalProb = 0.5,
39:   serverAddress = '10.1',
40:   stage = 1,
41:   backendAddresses = ['10.11', '10.12'],
42:   ttlTicks = DEFAULT_TTL_TICKS,
43:   cacheAddress = '10.20',
44:   replicationLagTicks = 3,
45:   dbPrimaryAddress = '10.30',
46:   dbReplicaAddress = '10.31',
47:   workerQueueAddress = '10.40',
48:   workerAddress = '10.41',
49:   jobDurationTicks = 2,
50:   dnsAddress = '10.60',
51:   dnsTtlTicks = DEFAULT_DNS_TTL_TICKS,
52:   routerLeftAddress = ROUTER_LEFT_ADDRESS,
53:   // Stage 6b seats live in addresses.js — the edge owns 20.1, the router re-seats to 20.254.
54:   routerRightAddress = ROUTER_RIGHT_ADDRESS,
55:   cdnAddress = CDN_ADDRESS,
56:   edgeTtlTicks = 10,
57: } = {}) {
58:   if (typeof arrivalProb !== 'number' || arrivalProb < 0 || arrivalProb > 1) {
59:     throw new Error(`engine: arrivalProb must be within [0, 1], got ${arrivalProb}`);
60:   }
61:   if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
62:     throw new Error(`engine: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
63:   }
64:   const rng = createRng(seed);
65:   const network = createNetwork();
66:   const cache = stage >= 3 ? createCache({ address: cacheAddress, ttlTicks }) : null;
67:   const database =
68:     stage >= 4
69:       ? createDatabase({
70:           primaryAddress: dbPrimaryAddress,
71:           replicaAddress: dbReplicaAddress,
72:           replicationLagTicks,
73:         })
74:       : null;
75:   const workerQueue =
