85:   // registration order); stages 1-5 carry nulls.
86:   const fabric = fabricForStage(stage, {
87:     serverAddress,
88:     dnsAddress,
89:     dnsTtlTicks,
90:     routerLeftAddress,
91:     routerRightAddress,
92:     cdnAddress,
