109:     network,
110:   });
111:   // The learner's own interactive client shares the crowd's network and
112:   // server pool but keeps its own browser and address; users.js keeps its
113:   // addresses so seeded tick sequences stay identical (PINS above).
114:   const clientBrowser = createBrowser({ name: 'Browser (You)', address: '10.2', network });
115:   const userPool = createUsers({ count: users, serverAddress });
116:   let tick = 0;
117:   let lastExchange = null;
118:   let lastMatchedRoute = null;
119:   let lastFrame = null;
