121:   // CHECKS (Stage 6b): left-network wire seats for browsers receiving
122:   // cross-subnet response frames (browser-seat.js); registered before a
123:   // trace runs.
124:   const ensureBrowserSeat = createBrowserSeatRegistry(network);
125: 
126:   // The trace machine owns the hop-by-hop trace state; the engine owns the
127:   // clock, the served-exchange record, and browser delivery — the machine
128:   // calls back into these closures as hops execute.
129:   const traceMachine = createTraceMachine({
130:     stage,
131:     serverAddress,
132:     servers,
133:     lb,
134:     network,
135:     cache,
136:     database,
137:     workerQueue,
138:     dns,
139:     cdn: edge,
140:     router,
141:     bumpTick: () => {
142:       tick += 1;
