144:     },
145:     getTick: () => tick,
146:     onServe: (exchange) => {
147:       lastExchange = exchange;
148:       lastMatchedRoute = exchange.routeId;
149:     },
150:     onFinish: (record) => {
151:       userPool.receiveResponse(record);
152:       if (record.from === '10.2') clientBrowser.receiveResponse(record);
153:     },
154:     // Stage 6 negative branch: an NX DNS answer renders the refusal card on
155:     // the browser and no GET ever reaches the server pool (no onFinish).
156:     onDnsFail: (record) => {
157:       if (record.from === '10.2') clientBrowser.receiveDnsFailure(record.request);
158:     },
159:     // B-6 negative branch: a transport refusal renders the connection-
