167:   return {
168:     step() {
169:       tick += 1;
170:       // TTL eviction happens once per tick, before anything is served:
171:       // expired entries are gone before this tick's work is priced.
172:       if (cache) cache.evictExpired(tick);
173:       // Stage 4+: replication advances one tick at a time.
174:       if (database) database.stepReplication(tick);
175:       // Stage 5: worker queue advances jobs and writes to database.
176:       if (workerQueue) workerQueue.step(database, tick);
177:       const arrivals = userPool.step(rng, arrivalProb);
178:       for (const r of arrivals) {
179:         network.deliverToQueue({
180:           id: `${tick}:${r.userId}`,
181:           from: r.from,
182:           to: r.to,
183:           request: r.request,
184:           atTick: tick,
185:         });
186:       }
187:       const servedBatch = servers.flatMap((s) => s.step(tick));
188:       if (servedBatch.length > 0) {
189:         lastExchange = servedBatch[servedBatch.length - 1];
190:         lastMatchedRoute = lastExchange.routeId;
191:         lastFrame = `${lastExchange.from} -> ${lastExchange.to} | ${lastExchange.request} => ${lastExchange.response}`;
192:         for (const item of servedBatch) {
193:           // Every served exchange is delivered back to its originating
194:           // browser; the learner's own interactive client additionally
195:           // renders anything it originated (trace items or 10.2 crowd rays).
196:           userPool.receiveResponse(item);
