211:       // CHECKS (Stage 6b): a CDN response frame crosses BACK through the
212:       // Router into the originating browser, so the browser needs a real
213:       // resolvable seat on the left network (browser-seat.js).
214:       if (stage >= 6) ensureBrowserSeat(from);
215:       const frame = traceMachine.step({ method, path, from });
216:       if (frame !== null) lastFrame = frame;
217:       return this.snapshot();
218:     },
219: 
220:     setUsers(n) {
221:       userPool.setCount(n);
222:     },
223: 
224:     // CHECKS: setWebFile routes an fs edit to the matching server address
225:     // — unknown mini-IP throws (fail-loud) and nothing else moves. The
226:     // edit invalidates nothing, so a stage-3+ cache keeps its OLD body
227:     // until the TTL expires.
228:     setWebFile(address, path, body) {
229:       const server = servers.find((s) => s.address === address);
230:       if (!server) {
231:         throw new Error(`engine: setWebFile — no server at mini-IP ${address}`);
232:       }
233:       server.writeFile(path, body);
234:     },
235: 
236:     // B-6 / B-6b / B-6c / B-6d / B-6e / B-6f fault flips live in
237:     // engine-faults.js (setServerDown, setCacheBypassed,
238:     // setDatabasePrimaryDown, setWorkerCrashed, setDnsDropped) — wiring
239:     // identical, each fail-loud on the component it names.
240:     ...createFaultSetters({ stage, servers, cache, database, workerQueue, dns }),
241: 
242:     snapshot() {
243:       const serverSnapshots = servers.map((s) => ({
244:         address: s.address,
245:         ...s.metrics(),
246:         down: s.isDown(),
247:         queue: s.queueSnapshot(),
248:         files: s.filesSnapshot(),
249:       }));
250:       const queueDepth = serverSnapshots.reduce((sum, s) => sum + s.queueDepth, 0);
251:       const served = serverSnapshots.reduce((sum, s) => sum + s.served, 0);
252:       const active = serverSnapshots.filter((s) => s.served > 0);
253:       const avgLatencyTicks =
254:         active.length === 0
255:           ? 0
256:           : active.reduce((sum, s) => sum + s.avgLatencyTicks, 0) / active.length;
257:       return {
258:         stage,
259:         tick,
260:         users: userPool.getCount(),
261:         serverAddress,
262:         queueDepth,
263:         served,
264:         avgLatencyTicks,
265:         refusedCount: network.refusedCount(),
266:         // B-6b: the failover skip tally rides the snapshot (stage-2 mission + loads).
267:         skippedCount: lb?.skippedCount() ?? 0,
268:         // B-6c: the pool's own origin-path tally (the cache is not consulted while bypassed, so it cannot tally there).
269:         bypassedCount: servers.reduce((sum, s) => sum + (s.bypassedCount?.() ?? 0), 0),
270:         // B-6d: pool-summed refused writes (each webserver tallies its own
271:         // share; the database's own failedWrites only moves on a direct
272:         // write() call, e.g. the Stage 5 worker commit) and the primary's
273:         // live ON/OFF flag read back from the component itself.
274:         failedWrites: servers.reduce((sum, s) => sum + (s.failedWrites?.() ?? 0), 0),
275:         primaryDown: database?.isPrimaryDown?.() ?? false,
276:         // B-6e: the worker's crash flag and re-delivery tally read back from
