278:         crashed: workerQueue?.isCrashed?.() ?? false,
279:         redelivered: workerQueue?.redelivered?.() ?? 0,
280:         lastExchange,
281:         queue: serverSnapshots[0].queue,
282:         files: serverSnapshots[0].files,
283:         servers: serverSnapshots,
284:         loadBalancer: lb ? lb.snapshot() : null,
285:         cache: cache ? cache.snapshot(tick) : null,
286:         database: database ? database.snapshot(tick) : null,
287:         workerQueue: workerQueue ? workerQueue.snapshot(tick) : null,
288:         dns: dns ? dns.snapshot(tick) : null,
289:         router: router ? router.snapshot() : null,
290:         cdn: edge ? edge.snapshot(tick) : null,
