1: // guard-claims — factory-kit CLAIM-LANGUAGE.md, mechanically enforced
2: // (strict mode). Every comment paragraph in js/**, css/**, test/**, e2e/**
3: // obeys three rules:
4: //   1. At most one claim keyword (CHECKS:, PINS:, DOCUMENTS:) per paragraph.
5: //   2. Guarantee words (guarantees, always, never, ensures, will) may appear
6: //      ONLY inside CHECKS: or PINS: paragraphs — never in untagged comments
7: //      and never in DOCUMENTS: paragraphs ("description of behavior, carrying
8: //      no guarantee").
9: //   3. Non-vacuity: fails if 0 source files or 0 claim tags are scanned.
10: import { readFileSync, readdirSync, statSync } from 'node:fs';
11: import { join, relative, sep, extname } from 'node:path';
